strings:
body { font: 14px/1.4 sans-serif; margin: 0; color: #0f1111; }
header { position: sticky; top: 0; z-index: 2; display: flex; gap: 12px; align-items: center;
         background: #131921; color: #fff; padding: 8px 12px; }
header a { color: #fff; }
header input { width: 360px; }
.layout { display: flex; gap: 16px; padding: 12px; }
.filters { width: 180px; flex: none; }
.filters label { display: block; }
.grid { display: grid; grid-template-columns: repeat(3, 220px); gap: 16px; }
.card img { width: 220px; height: 160px; object-fit: cover; }
.card h2 { font-size: 15px; font-weight: 400; margin: 4px 0; }
.rating { display: flex; gap: 6px; align-items: center; font-size: 12px; }
.price { font-size: 13px; }
.price .whole { font-size: 24px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.badge { background: #232f3e; color: #fff; font-size: 11px; padding: 0 4px; }
.shelf { display: flex; gap: 12px; overflow-x: auto; width: 720px; scroll-snap-type: x mandatory; }
.shelf .card { flex: none; width: 160px; }
.shelf img { width: 160px; height: 110px; }
.cookies { position: fixed; bottom: 0; left: 0; right: 0; background: #fff; border-top: 2px solid #f90;
           padding: 8px 12px; display: flex; gap: 12px; align-items: center; }
